#include <stdio.h>
#include <stdlib.h>

#define MAX(a,b) (a) > (b) ? (a) : (b)

int getResult(int n, int ranges[][2]);
int cmp(const void* a, const void* b);

int main() {
    int n;
    scanf("%d", &n);

    int ranges[n][2];
    for(int i=0; i<n; i++) {
        int center = i * 100;

        int r;
        scanf("%d", &r);

        ranges[i][0] = center - r;
        ranges[i][1] = center + r;
    }

    printf("%d\n", getResult(n, ranges));

    return 0;
}

int getResult(int n, int ranges[][2]) {
    int ans = 0;

    // 按起始位置升序，起始位置相同，则继续按结束位置降序
    qsort(ranges, n, sizeof(int*), cmp);

    int t = ranges[0][1]; // 上一个区间的结束位置

    for(int i=1; i<n; i++) {
        // 当前区间的【开始位置，结束位置】
        int s = ranges[i][0];
        int e = ranges[i][1];

        if(t >= s) {
            // 有交集
            // 合并后的新区间将变为下一轮的上一个区间，t为新区间的结束位置
            t = MAX(e, t);
        } else {
            // 没有交集，则统计区间间隙 s - t
            ans += s - t;
            // 当前区间变为下一轮的上一个区间，更新t
            t = e;
        }
    }

    return ans;
}

int cmp(const void* a, const void* b) {
    int* A = (int*) a;
    int* B = (int*) b;
    return A[0] != B[0] ? A[0] - B[0] : B[1] - A[1];
}
